def execute(plan, out='/app/output/trajectory.npz', score=True):
    s=Session('/app/instance.json',render=False);s.reset();s.record_start();p=s.primitives();now=time.time()
    def mv(pos,speed=.12,settle=0):
        r=p['move_tip'](pos,speed=speed,settle=settle)
        if r['ik_failures']:print('IK failures',r,flush=True)
    def loc(pt):
        x,y=s.geo.mm_to_world(pt[0],pt[1]);return [x,y,.02-pt[2]/1000]
    for j,(k,pts) in enumerate(plan):
        k=int(k);w=s.wells()[k];tip=s.tip_pose()[0];mv([tip[0],tip[1],.055],.13,2)
        mv([*w['center_xy'],.055],.2,1);mv([*w['center_xy'],.024],.09,3);mv([*w['center_xy'],.055],.13,1)
        start=loc(pts[0]);mv([start[0],start[1],.05],.2,1);mv(start,.05,3)
        prev=pts[0]
        for pt in pts[1:]:
            vertical=abs(pt[0]-prev[0])+abs(pt[1]-prev[1])<.001
            light=pt[2]<1
            # Allow depth transitions to settle before crossing another color.
            if vertical:mv(loc([pt[0],pt[1],.4 if light else pt[2]]),.04,4)
            else:mv(loc([pt[0],pt[1],.4 if light else pt[2]]),.18 if light else .065,2)
            prev=pt
        end=loc(pts[-1]);mv([end[0],end[1],.055],.1,3)
        if j%10==0:
            print('stroke',j+1,'/',len(plan),'steps',s.n_steps,'time',round(time.time()-now,1),flush=True)
            Image.fromarray(s.canvas()).save('/app/output/current.png')
    actions=s.record_stop();s.save_trajectory(actions,out)
    Image.fromarray(s.canvas()).save('/app/output/canvas.png')
    print('DONE',len(actions),'contacts',len(s.strokes()),'sha',s.state_sha(),flush=True)
    if score:
        result=s.status();json.dump(result,open('/app/output/metrics.json','w'),indent=2);print(result,flush=True)
    return s
if __name__=='__main__':
    execute(json.load(open('/app/output/plan.json')))
